// Demonstrating tunable consistency in a Java application using the DataStax Cassandra Driver
import com.datastax.oss.driver.api.core.CqlSession;
import com.datastax.oss.driver.api.core.cql.BoundStatement;
import com.datastax.oss.driver.api.core.cql.PreparedStatement;
import com.datastax.oss.driver.api.core.cql.DefaultConsistencyLevel;

public class CassandraClientDemo {
    public void writeWithQuorum(CqlSession session, String userId, String payload) {
        PreparedStatement stmt = session.prepare(
            "INSERT INTO user_events (user_id, event_data) VALUES (?, ?)"
        );

        BoundStatement bound = stmt.bind(userId, payload)
            // Enforcing QUORUM trades availability for stronger consistency
            .setConsistencyLevel(DefaultConsistencyLevel.QUORUM);

        session.execute(bound);
    }
}
